sys_script_include.script:
/**
 * Script Include: ConfigNowImporter
 * Scope:          x_2160899_driftw_0  (ConfigurationNOW)
 * Accessible from: This application scope only
 *
 * Loads a snapshot JSON (as downloaded from the Current Instance Settings page
 * or returned by GET /current on any instance) into this instance's tables via
 * ConfigNowWriter, as its own instance CI. The writer is change-only, so
 * re-importing the same snapshot writes nothing.
 *
 *   new ConfigNowImporter().importSnapshot(obj)                  // obj or JSON string
 *   new ConfigNowImporter().importSnapshot(obj, { force: true }) // allow older snapshot
 *   new ConfigNowImporter().importSnapshot(obj, { allowLocal: true }) // allow this instance's own
 *
 * Safety:
 *  - validates schema, instance name and timestamp
 *  - refuses a snapshot OLDER than what is already stored for that instance
 *    (unless force), so an old file can't roll an instance back by accident
 *  - refuses a snapshot of THIS instance unless allowLocal: its CI belongs to
 *    the local collector
 *  - refuses snapshots larger than config.maxImportItems
 *  - all timestamps (first_seen / last_changed / last_collected) use the
 *    snapshot's collected_at, not the import time
 */
var ConfigNowImporter = Class.create();
ConfigNowImporter.prototype = {

    SUPPORTED_SCHEMAS: { 'configurationnow.snapshot/0.1': true },

    initialize: function (options) {
        this.options = options || {};
        this.config = this.options.config || ConfigNowConfig.get();
    },

    importSnapshot: function (snapshot, opts) {
        opts = opts || {};
        if (typeof snapshot == 'string') snapshot = JSON.parse(snapshot);
        var err = this.validate(snapshot);
        if (err) throw new Error(err);

        var name = snapshot.instance.instance_name;
        if (name == gs.getProperty('instance_name') && !opts.allowLocal) {
            throw new Error('Snapshot is of THIS instance (' + name + '). Its CI is maintained by the local collector ' +
                '(Collect now / daily job); use allowLocal to import it anyway.');
        }
        var existing = this._storedCollectedAt(name);
        if (existing && snapshot.collected_at < existing && !opts.force) {
            throw new Error('Snapshot for ' + name + ' (' + snapshot.collected_at + ' UTC) is older than the stored data (' +
                existing + ' UTC). Use force to import it anyway.');
        }
        var res = new ConfigNowWriter({ config: this.config }).persist(snapshot, { timestamp: snapshot.collected_at, source: 'import' });
        return {
            instance_name: name,
            instance_sys_id: res.instance_sys_id,
            collected_at: snapshot.collected_at,
            local: name == gs.getProperty('instance_name'),
            totals: res.totals,
            categories: res.categories
        };
    },

    /** Returns an error message, or '' when the snapshot is importable. */
    validate: function (s) {
        if (!s || typeof s != 'object') return 'Snapshot is not a JSON object';
        if (s.result && s.result.schema) return 'This looks like a REST response – import its "result" object';
        if (!this.SUPPORTED_SCHEMAS[s.schema]) return 'Unsupported snapshot schema: ' + s.schema;
        if (!s.instance || !s.instance.instance_name) return 'Snapshot has no instance.instance_name';
        if (!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(s.collected_at || '')) return 'Snapshot collected_at is missing or malformed';
        if (!s.categories || typeof s.categories != 'object') return 'Snapshot has no categories';
        var n = 0;
        for (var c in s.categories) {
            var cat = s.categories[c];
            if (!cat || Object.prototype.toString.call(cat.items) != '[object Array]') return 'Category ' + c + ' has no items array';
            n += cat.items.length;
        }
        if (n > this.config.maxImportItems) return 'Snapshot has ' + n + ' items (limit ' + this.config.maxImportItems + ')';
        return '';
    },

    _storedCollectedAt: function (name) {
        var gr = new GlideRecord(this.config.tables.instance);
        gr.addQuery('instance_name', name);
        gr.setLimit(1);
        gr.query();
        return gr.next() ? (gr.getValue('last_collected') || '') : '';
    },

    type: 'ConfigNowImporter'
};
